mapper.insert:
MERGE INTO products t USING ( VALUES
( #{item.products_name}, #{item.price}, #{item.stock}, #{item.description} )
) AS s(products_name, price, stock, description) ON t.products_name = s.products_name WHEN MATCHED THEN UPDATE SET price = s.price, stock = s.stock, description = s.description WHEN NOT MATCHED THEN INSERT ( products_name, price, stock, description ) VALUES ( s.products_name, s.price, s.stock, s.description )
